const items = $input.all();
const results = items[0].json.results;
return results.map(p => ({ json: { url: p.url, name: p.name } }));

const runId = $('Create Run').first().json.run_id;
const now = new Date().toISOString();
const items = $input.all();

return items.map(item => {
  const p = item.json;

  const pokemon_name = (p.name || '').trim() || 'unknown';
  const base_experience = p.base_experience != null ? p.base_experience : 'NULL';
  const height = p.height != null ? p.height : 'NULL';
  const weight = p.weight != null ? p.weight : 'NULL';

  const main_type = (p.types && p.types.length > 0)
    ? p.types[0].type.name
    : 'unknown';

  const has_official_artwork = !!(p.sprites
    && p.sprites.other
    && p.sprites.other['official-artwork']
    && p.sprites.other['official-artwork'].front_default);

  const has_front_sprite = !!(p.sprites && p.sprites.front_default);

  const sql = `INSERT INTO pokemon (pokemon_id, pokemon_name, base_experience, height, weight, main_type, has_official_artwork, has_front_sprite, source_last_updated_at, ingested_at, run_id) VALUES (${p.id}, '${pokemon_name.replace(/'/g, "''")}', ${base_experience}, ${height}, ${weight}, '${main_type}', ${has_official_artwork}, ${has_front_sprite}, '${now}', '${now}', ${runId}) ON CONFLICT (pokemon_id) DO UPDATE SET pokemon_name=EXCLUDED.pokemon_name, base_experience=EXCLUDED.base_experience, height=EXCLUDED.height, weight=EXCLUDED.weight, main_type=EXCLUDED.main_type, has_official_artwork=EXCLUDED.has_official_artwork, has_front_sprite=EXCLUDED.has_front_sprite, source_last_updated_at=EXCLUDED.source_last_updated_at, ingested_at=EXCLUDED.ingested_at, run_id=EXCLUDED.run_id;`;

  return { json: { query: sql } };
});
